/**
 * Enumerating the abilities of an object with stable keys. Owner: WP9. The object's characteristics (rules/characteristics.ts, after the layers) already
 * hold every ability it has, each with its key (statics/abilities.ts builds them):
 *   p:<face>:<index>       printed ability, FaceDef.abilities[index] of that face
 *   k:<face>:<index>:<n>   generated by the keyword library from the printed keyword ability at that index
 *   g:<effectId>:<n>       granted by a continuous effect (layer 6); the expansion of a granted keyword appends :<j>
 *   r:basic:<W|U|B|R|G>    rule-generated "{T}: Add {X}" of a basic land type (CR 305.6)
 *   c:<effectId>:<face>:<index>[:<n>]  M6-2 (m6 design E5): copied by a copy effect (CR 707.2), and the expansions of copied keywords
 * Keys are stable across states, so a UI or bot can refer to an ability by (object id, key). An ability that is removed (CR 613.1f) is simply not listed.
 */
import type { AbilityDef, ActivatedAbilityDef } from '../types/ability';
import type { ObjectId } from '../types/ids';
import type { AbilityRef, GameObject, GameState, ZoneKind } from '../types/state';
import type { CharAbility } from '../statics/api';
import { charsOfObject, type Chars } from './characteristics';

export { BASIC_LAND_MANA, basicKey, grantedKey, keywordKey, printedKey } from '../statics/abilities';

/** One ability of an object, with its stable key and where it comes from (the `origin` is the `source` an `AbilityRef` would carry). */
export interface AbilityInfo {
  key: string;
  origin: AbilityRef['source'];
  /** Face index and printed index (index is -1 for abilities that are not printed on the card). */
  face: number;
  index: number;
  def: AbilityDef;
  /** Effect id that granted it (origin 'granted'). */
  grantedBy?: string;
}

export interface ActivatedInfo extends AbilityInfo {
  def: ActivatedAbilityDef;
}

const toInfo = (a: CharAbility): AbilityInfo => ({ key: a.key, origin: a.origin, face: a.face, index: a.index, def: a.def, ...(a.grantedBy !== undefined ? { grantedBy: a.grantedBy } : {}) });

/** All abilities of an object that its characteristics give it (not yet filtered by zone), in the order printed, keyword-generated, rule, granted. */
export function abilitiesFromChars(c: Chars): AbilityInfo[] {
  return c.abilities.map(toInfo);
}

export function enumerateAbilities(s: GameState, o: GameObject): AbilityInfo[] {
  return abilitiesFromChars(charsOfObject(s, o));
}

export function activatedAbilities(s: GameState, o: GameObject): ActivatedInfo[] {
  return enumerateAbilities(s, o).filter((a): a is ActivatedInfo => a.def.kind === 'activated');
}

export function findAbility(s: GameState, id: ObjectId, key: string): AbilityInfo | undefined {
  const o = s.objects[id];
  return o ? enumerateAbilities(s, o).find((a) => a.key === key) : undefined;
}

export const isManaAbility = (def: AbilityDef): boolean => def.kind === 'activated' && def.isMana === true;

/** Zones an activated ability can be activated from (CR 113.6): the battlefield unless it says otherwise. */
export const activationZones = (def: ActivatedAbilityDef): readonly ZoneKind[] => def.zone ?? ['battlefield'];

/** Does the activated ability function while its source is in `zone`? (CR 113.6) */
export const activatesFrom = (def: ActivatedAbilityDef, zone: ZoneKind): boolean => activationZones(def).includes(zone);

/**
 * The ability definition behind an ability object on the stack. An ability that is not printed text of a living object (granted, keyword-generated, delayed, ...) exists
 * independently of its source (CR 113.7a): its definition is `inline`. Failing that (an object put on the stack by code that does not record it) the definition is
 * found again by the key among the abilities the source has now.
 */
export function abilityDefOnStack(s: GameState, o: GameObject): AbilityDef | undefined {
  const info = o.stack;
  const ref: AbilityRef | undefined = info?.abilityRef;
  if (!info || !ref) return undefined;
  if (info.inline) return info.inline;
  if (ref.source === 'printed' && ref.index >= 0) return s.defs[o.defId]?.faces[ref.face]?.abilities[ref.index];
  if (ref.key === undefined || !info.sourceId) return undefined;
  const source = s.objects[info.sourceId];
  if (source) return findAbility(s, source.id, ref.key)?.def;
  // M6-2 (E5): a copied (`c:`), granted or generated ability whose source left is found among its last known characteristics (CR 113.7a, 608.2h)
  const lk = s.lki[info.sourceId];
  return lk?.chars ? abilitiesFromChars(lk.chars).find((a) => a.key === ref.key)?.def : undefined;
}
